///< mantissa bits for doubles.
#define JBM_2xF64_BITS_SIGN __lsx_vreplgr2vr_d (JBM_F64_BITS_SIGN)
///< sign bits for doubles.
#define JBM_2xF64_CBRT2 ((JBM2xF64) \
